arguments.command:
# Use the structured log reader NuGet package via a small C# script
cat > /tmp/ReadBinlog.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net11.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.*" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/ReadBinlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);
var errors = new List<(string project, string code, string file, int line, string msg)>();
var warnings = new List<(string project, string code, string file, int line, string msg)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = (BaseNode)e;
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }
    errors.Add((proj, e.Code ?? "", e.File ?? "", e.LineNumber, e.Text ?? ""));
});

build.VisitAllChildren<Warning>(w => {
    var node = (BaseNode)w;
    var proj = "";
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }
    warnings.Add((proj, w.Code ?? "", w.File ?? "", w.LineNumber, w.Text ?? ""));
});

Console.WriteLine($"=== BUILD RESULT: {(build.Succeeded ? "SUCCESS" : "FAILED")} ===");
Console.WriteLine($"\n=== ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project)) {
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g)
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.msg}");
}

if (warnings.Any(w => w.code.StartsWith("CS") || w.code.StartsWith("NU"))) {
    Console.WriteLine($"\n=== RELEVANT WARNINGS ===");
    foreach (var w in warnings.Where(w => w.code.StartsWith("CS") || w.code.StartsWith("NU")))
        Console.WriteLine($"  [{w.code}] {w.project} - {w.file}({w.line}): {w.msg}");
}

// Show project dependency info
Console.WriteLine("\n=== PROJECT BUILD ORDER & DEPENDENCIES ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"  {p.Name} -> {(p.Succeeded ? "OK" : "FAILED")}");
});
CSHARP

