using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check if Api.csproj had its own errors or just failed due to dependency
Console.WriteLine("=== ALL ERRORS BY PROJECT (with file details) ===");
build.VisitAllChildren<Error>(e => {
    var node = (BaseNode)e;
    var proj = "";
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }
    Console.WriteLine($"  Project={proj} Code={e.Code} File={e.File}:{e.LineNumber} Msg={e.Text}");
});

// Check project references
Console.WriteLine("\n=== PROJECT REFERENCES (from items) ===");
build.VisitAllChildren<Item>(i => {
    if (i.Name == "ProjectReference") {
        var node = (BaseNode)i;
        var proj = "";
        while (node.Parent != null) {
            node = (BaseNode)node.Parent;
            if (node is Project p) { proj = p.Name; break; }
        }
        Console.WriteLine($"  {proj} -> {i.Text}");
    }
});

// Check package references  
Console.WriteLine("\n=== PACKAGE REFERENCES ===");
build.VisitAllChildren<Item>(i => {
    if (i.Name == "PackageReference") {
        var node = (BaseNode)i;
        var proj = "";
        while (node.Parent != null) {
            node = (BaseNode)node.Parent;
            if (node is Project p) { proj = p.Name; break; }
        }
        Console.WriteLine($"  {proj} -> {i.Text}");
    }
});
