using Microsoft.Build.Logging.StructuredLogger;
using System;

var build = BinaryLog.ReadBuild(args[0]);

// Dump the tree structure for Services.csproj to find package refs
Console.WriteLine("=== TREE DUMP (depth-limited) ===");
void DumpNode(BaseNode node, int depth, int maxDepth) {
    if (depth > maxDepth) return;
    var indent = new string(' ', depth * 2);
    var type = node.GetType().Name;
    var text = node.ToString();
    if (text != null && (
        text.Contains("Newtonsoft") || 
        text.Contains("PackageReference") ||
        text.Contains("Package") ||
        (type == "Property" && text.Contains("Json"))
    )) {
        Console.WriteLine($"{indent}[{type}] {text}");
    }
    if (node is TreeNode tn) {
        foreach (BaseNode child in tn.Children) {
            DumpNode(child, depth + 1, maxDepth);
        }
    }
}
DumpNode(build, 0, 20);
