cat > /tmp/ReadBinlog.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;
using System;

var build = BinaryLog.ReadBuild(args[0]);

// Get the actual text/value of PackageReference items
Console.WriteLine("=== PACKAGE REFERENCE ITEMS (detailed) ===");
build.VisitAllChildren<Item>(i => {
    // Walk up to find project
    var node = (BaseNode)i;
    var proj = "";
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; break; }
    }

    // Check parent folder name
    var parentName = "";
    if (i.Parent is Folder f) parentName = f.Name;
    if (i.Parent is AddItem ai) parentName = ai.Name;

    if (parentName == "PackageReference") {
        Console.WriteLine($"  {proj}: {i.Name} = {i.Text}");
        foreach (var c in i.Children) {
            Console.WriteLine($"    metadata: {c}");
        }
    }
});

// Also try looking at source files in the binlog
Console.WriteLine("\n=== SOURCE FILES CONTENT (if embedded) ===");
var sourceFiles = build.FindChildrenRecursive<SourceFile>();
if (sourceFiles != null) {
    foreach (var sf in sourceFiles) {
        Console.WriteLine($"  SourceFile: {sf}");
    }
}

// Look at the csproj content via embedded files
Console.WriteLine("\n=== SEARCHING FOR .csproj CONTENT ===");
build.VisitAllChildren<Message>(m => {
    if (m.Text != null && m.Text.Contains("PackageReference") && m.Text.Contains("Include")) {
        Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 300))}");
    }
});

// Let's look at properties for Services project that mention packages
Console.WriteLine("\n=== SERVICES PROJECT PROPERTIES WITH 'Package' ===");
build.VisitAllChildren<Property>(p => {
    var node = (BaseNode)p;
    var proj = "";
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project pr) { proj = pr.Name; break; }
    }
    if (proj == "Services.csproj" && p.Name != null && 
        (p.Name.Contains("Package") || p.Name.Contains("Newtonsoft"))) {
        Console.WriteLine($"  {p.Name} = {p.Value?.Substring(0, Math.Min(p.Value.Length, 200))}");
    }
});
