using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.IO;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);

// Try to get embedded files from the binlog
Console.WriteLine("=== EMBEDDED FILES IN BINLOG ===");
var archiveFile = args[0];
var reader = new BinLogReader();
var records = reader.ReadRecords(archiveFile);
foreach (var record in records) {
    if (record.Args is Microsoft.Build.Framework.BuildMessageEventArgs msg) {
        // skip
    }
}

// Try reading raw embedded content
Console.WriteLine("\n=== LOOKING FOR SOURCEFILESTHATEXIST ===");
build.VisitAllChildren<Item>(i => {
    var parentName = i.Parent?.ToString() ?? "";
    if (parentName.Contains("SourceFilesT") || parentName.Contains("Compile") || i.Name == "Compile") {
        var node = (BaseNode)i;
        var proj = "";
        while (node.Parent != null) {
            node = (BaseNode)node.Parent;
            if (node is Project p) { proj = p.Name; break; }
        }
        if (proj.Contains("Services"))
            Console.WriteLine($"  {proj} [{i.Parent?.GetType().Name}:{parentName}]: {i.Text} / {i.Name}");
    }
});

// Dump all NamedNode types for Services.csproj (top-level categories)
Console.WriteLine("\n=== SERVICES.CSPROJ TOP-LEVEL NAMED CHILDREN ===");
build.VisitAllChildren<Project>(p => {
    if (p.Name == "Services.csproj") {
        Console.WriteLine($"  Project: {p.Name} (children: {p.Children.Count})");
        foreach (var c in p.Children) {
            Console.WriteLine($"    [{c.GetType().Name}] {c}");
        }
        break;
    }
});
