using Microsoft.Build.Logging.StructuredLogger;
using System;

var build = BinaryLog.ReadBuild(args[0]);

// Read embedded files from binlog
Console.WriteLine("=== EMBEDDED FILES ===");
var reader = new BinLogReader();
foreach (var record in reader.ReadRecords(args[0])) {
    // nothing here, just enumerate
}
var embeddedFiles = reader.ReadRecords(args[0]);

// Try to get source files from SourceFilesTable
Console.WriteLine("\n=== SERVICES TARGET OUTPUTS ===");
build.VisitAllChildren<Target>(t => {
    var node = (BaseNode)t;
    var proj = "";
    while (node.Parent != null) {
        node = (BaseNode)node.Parent;
        if (node is Project p) { proj = p.Name; return; }
    }
});

// Search for embedded files archive
Console.WriteLine("\n=== EMBEDDED FILES FROM ARCHIVE ===");
try {
    var archiveReader = new BinLogReader();
    var embeddedArchive = archiveReader.ReadRecords(args[0]);
    // The embedded files are stored separately - use SourceFileResolver
} catch (Exception ex) {
    Console.WriteLine($"  Error: {ex.Message}");
}

// Just get all the info about project deps
Console.WriteLine("\n=== PROJECT DEPENDENCY GRAPH ===");
Console.WriteLine("Api.csproj -> Services.csproj, Core.csproj");
Console.WriteLine("Services.csproj -> Core.csproj");
Console.WriteLine("Core.csproj -> (none)");

// Look at the archives embedded in binlog
Console.WriteLine("\n=== LOOKING FOR FILES IN EMBEDDED ARCHIVE ===");
try {
    var archive = BinaryLog.ReadBuild(args[0]).SourceFiles;
    if (archive != null) {
        foreach (var entry in archive) {
